// src/data/egyptGeoData.ts
var rawNodes = [];
function gov(id, name, lat, lng, aliases) {
	rawNodes.push({
		id,
		name,
		level: "governorate",
		parentId: "eg",
		governorateId: id,
		lat,
		lng,
		aliases
	});
	return id;
}
function mkz(id, name, governorateId, lat, lng, aliases) {
	rawNodes.push({
		id,
		name,
		level: "markaz",
		parentId: governorateId,
		governorateId,
		markazId: id,
		lat,
		lng,
		aliases
	});
	return id;
}
function cty(id, name, markazId, governorateId, lat, lng, aliases) {
	rawNodes.push({
		id,
		name,
		level: "city",
		parentId: markazId,
		governorateId,
		markazId,
		cityId: id,
		lat,
		lng,
		aliases
	});
	return id;
}
function vil(id, name, cityId, markazId, governorateId, lat, lng, aliases) {
	rawNodes.push({
		id,
		name,
		level: "village",
		parentId: cityId,
		governorateId,
		markazId,
		cityId,
		lat,
		lng,
		aliases
	});
	return id;
}
rawNodes.push({
	id: "eg",
	name: "مصر",
	level: "country",
	parentId: null,
	governorateId: "",
	lat: 26.8206,
	lng: 30.8025,
	aliases: ["جمهورية مصر العربية", "Egypt"]
});
function addMarkazWithUnits(govId, mkzId, mkzName, mkzLat, mkzLng, cities, mkzAliases) {
	mkz(mkzId, mkzName, govId, mkzLat, mkzLng, mkzAliases);
	cities.forEach((c, idx) => {
		const cLat = c.lat ?? mkzLat + idx * .002;
		const cLng = c.lng ?? mkzLng + idx * .002;
		cty(c.id, c.name, mkzId, govId, cLat, cLng, c.aliases);
		c.villages?.forEach((v, vIdx) => {
			vil(v.id, v.name, c.id, mkzId, govId, v.lat ?? cLat + (vIdx + 1) * .0015, v.lng ?? cLng + (vIdx + 1) * .0015, v.aliases);
		});
	});
}
