function attachAdoptionEvents() {
	const dismissBtn = document.getElementById("dismiss-adoption-advice-btn");
	if (dismissBtn) dismissBtn.addEventListener("click", () => {
		state.dismissAdvice();
		const banner = document.getElementById("meow-adoption-advice-banner");
		if (banner) banner.remove();
	});
	document.querySelectorAll(".adopt-type-btn").forEach((btn) => {
		btn.addEventListener("click", () => {
			const type = btn.getAttribute("data-adopt-type");
			state.applyAdoptionFiltersWithLoading({ adoptionType: type }, "جاري تحديث حالات التبني...");
		});
	});
	const searchInput = document.getElementById("adoption-search-input");
	if (searchInput) searchInput.addEventListener("input", (e) => {
		const inputEl = e.target;
		const val = inputEl.value;
		const caret = inputEl.selectionStart ?? val.length;
		state.setAdoptionFilters({ breed: val });
		const restored = document.getElementById("adoption-search-input");
		if (restored) {
			restored.focus();
			try {
				restored.setSelectionRange(caret, caret);
			} catch {}
		}
	});
	const sortBySelect = document.getElementById("adoption-sort-by");
	if (sortBySelect) sortBySelect.addEventListener("change", (e) => {
		state.setAdoptionFilters({ sortBy: e.target.value });
	});
	const gridScope = document.querySelector("[data-purpose=\"pet-listings-grid\"]");
	(gridScope ? gridScope.querySelectorAll(".toggle-save-pet-btn") : []).forEach((btn) => {
		btn.addEventListener("click", (e) => {
			e.stopPropagation();
			const petId = btn.getAttribute("data-pet-save-id");
			if (petId) state.toggleSavePet(petId);
		});
	});
	(gridScope ? gridScope.querySelectorAll("[data-pet-detail-id]") : []).forEach((trigger) => {
		trigger.addEventListener("click", (e) => {
			if (e.target.closest(".toggle-save-pet-btn, .meow-more-menu-container")) return;
			const petId = trigger.getAttribute("data-pet-detail-id");
			const pet = state.getFilteredAdoptionPets().find((p) => p.id === petId);
			if (pet) state.setSelectedPetForDetail(pet);
		});
	});
	document.querySelectorAll(".send-adoption-request-btn").forEach((btn) => {
		btn.addEventListener("click", (e) => {
			e.stopPropagation();
			const petId = btn.getAttribute("data-pet-request-id");
			const pet = state.getFilteredAdoptionPets().find((p) => p.id === petId);
			if (pet) state.setSelectedPetForRequest(pet);
		});
	});
	attachPullToRefresh(document.getElementById("adoption-view-root"), {
		isBlocked: () => Boolean(state.isNotificationsOpen() || state.isSettingsOpen() || state.getSelectedPetForDetail() || state.getSelectedPetForRequest() || state.isAddPetModalVisible() || state.getIsFilterModalOpen() || state.isEditOwnerModalVisible() || state.isSavedPetsVisible() || state.isContactOpen() || state.getPendingBlockTarget() || state.getPendingReportTarget()),
		onRefresh: () => {
			state.refreshFeed("adoption");
			showMobileToast("تم تحديث قائمة التبني", "success", 1600);
		}
	});
}
// src/utils/petFormatters.ts
function formatPetSpecies(species) {
	return species === "dog" ? "كلب 🐶" : "قطة 🐱";
}
function formatPetSpeciesShort(species) {
	return species === "dog" ? "كلب" : "قطة";
}
function formatPetAgeFull(ageYears, ageMonths) {
	const y = Number.isFinite(ageYears) && ageYears > 0 ? ageYears : 0;
	const m = Number.isFinite(ageMonths) && ageMonths > 0 ? ageMonths : 0;
	if (y > 0 && m > 0) return `${y} سنة و ${m} شهر`;
	if (y > 0) return `${y} سنة`;
	if (m > 0) return `${m} شهر`;
	return "";
}
function formatVaccinationStatus(status) {
	if (status === "fully_vaccinated") return "مُطعم بالكامل";
	if (status === "partially_vaccinated") return "مطعم جزئياً";
	return "غير مُطعم";
}
function formatPetLocation(pet) {
	const lineage = resolveLocationLineage(pet);
	const parts = [];
	const pushUnique = (val) => {
		const clean = (val || "").trim();
		if (!clean) return;
		if (!parts.includes(clean)) parts.push(clean);
	};
	pushUnique(lineage.village?.name || pet.village || pet.area);
	pushUnique(lineage.city?.name || pet.city);
	pushUnique(lineage.markaz?.name || pet.markaz);
	pushUnique(lineage.governorate?.name || pet.governorate);
	return parts.join("، ");
}
