function getCustomStickers() {
	if (typeof window === "undefined") return [];
	try {
		return JSON.parse(localStorage.getItem("meow_custom_stickers") || "[]");
	} catch {
		return [];
	}
}
function saveCustomSticker(imageUrl, title = "استيكر مخصص") {
	const stickers = getCustomStickers();
	const newStk = {
		id: `stk_${Date.now()}`,
		imageUrl,
		title,
		createdAt: (/* @__PURE__ */ new Date()).toISOString()
	};
	stickers.unshift(newStk);
	if (typeof window !== "undefined") localStorage.setItem("meow_custom_stickers", JSON.stringify(stickers));
	return newStk;
}
function deleteCustomSticker(id) {
	const stickers = getCustomStickers().filter((s) => s.id !== id);
	if (typeof window !== "undefined") localStorage.setItem("meow_custom_stickers", JSON.stringify(stickers));
}
