function buildGroupCoverGalleryItems(pet) {
	const members = pet.groupMembers || [];
	const result = [];
	const seenUrl = /* @__PURE__ */ new Set();
	const pushUnique = (item) => {
		const cleanUrl = (item.url || "").trim();
		if (!cleanUrl || result.length >= 10 || seenUrl.has(cleanUrl)) return;
		seenUrl.add(cleanUrl);
		result.push({
			...item,
			url: cleanUrl
		});
	};
	if (pet.photoEntries && pet.photoEntries.length > 0) pet.photoEntries.filter((e) => e.kind === "collective").forEach((e) => {
		pushUnique({
			url: e.url,
			label: e.label || "صورة جماعية للمجموعة",
			kind: "collective"
		});
	});
	(pet.sharedGroupPhotos || []).forEach((url) => {
		pushUnique({
			url,
			label: "صورة جماعية للمجموعة",
			kind: "collective"
		});
	});
	members.forEach((m) => {
		const first = m.individualPhotos?.[0];
		if (first) pushUnique({
			url: first,
			label: m.name,
			kind: "individual",
			petId: m.petId
		});
	});
	if (result.length === 0) (pet.photos || []).forEach((url) => {
		pushUnique({
			url,
			label: pet.name,
			kind: "individual"
		});
	});
	return result;
}
