function getStepLabel(step) {
	switch (step) {
		case "welcome": return "أهلاً بك";
		case "auth_method": return authMode === "login" ? "تسجيل الدخول" : "إنشاء حساب";
		case "owner_details": return "بيانات المالك";
		case "has_pet": return "هل تمتلك أليفاً؟";
		case "pet_details": return "بيانات المياو";
		default: return "";
	}
}
function renderStepDots(currentStep) {
	const steps = [
		"welcome",
		"auth_method",
		"owner_details",
		"has_pet",
		"pet_details"
	];
	const currentIndex = steps.indexOf(currentStep);
	return steps.map((s, idx) => {
		const isCompleted = idx <= currentIndex;
		const isCurrent = idx === currentIndex;
		const isFuture = idx > currentIndex;
		return `
        <button
          type="button"
          data-onboarding-step="${s}"
          ${isFuture ? "disabled" : ""}
          aria-label="${getStepLabel(s)}"
          title="${getStepLabel(s)}"
          class="onboarding-step-dot h-2 rounded-full transition-all duration-300 ${isFuture ? "cursor-default" : "cursor-pointer"} ${isCurrent ? "w-6 bg-[#e67e22]" : isCompleted ? "w-2.5 bg-[#e67e22]/60" : "w-2 bg-[#d6c7b2]"}"
        ></button>
      `;
	}).join("");
}
function renderStepContent(step) {
	switch (step) {
		case "welcome": return renderWelcomeStep();
		case "auth_method": return renderAuthMethodStep();
		case "owner_details": return renderOwnerDetailsStep();
		case "has_pet": return renderHasPetStep();
		case "pet_details": return renderPetDetailsStep();
		default: return renderWelcomeStep();
	}
}
