// src/ui/modals/FilterModal.ts
function nodesToOptions(nodes, allLabel) {
	return [{
		value: "",
		label: allLabel
	}, ...nodes.map((node) => ({
		value: node.id,
		label: node.name,
		searchText: node.aliases?.join(" ")
	}))];
}
function getBreedOptions(species, isHybrid = false, extraValue = "") {
	const baseList = species === "dog" ? DOG_BREEDS : species === "cat" ? CAT_BREEDS : Array.from(/* @__PURE__ */ new Set([...CAT_BREEDS, ...DOG_BREEDS]));
	const cleanedExtra = extraValue.trim();
	const list = cleanedExtra && cleanedExtra !== "none" && !baseList.includes(cleanedExtra) ? [cleanedExtra, ...baseList] : baseList;
	if (isHybrid) return [
		{
			value: "",
			label: "الكل"
		},
		{
			value: "none",
			label: "بدون هجين"
		},
		...list.map((b) => ({
			value: b,
			label: b
		}))
	];
	return [{
		value: "",
		label: "الكل"
	}, ...list.map((b) => ({
		value: b,
		label: b
	}))];
}
function getMarkazOptionsForFilter(governorateId) {
	if (!governorateId) return [{
		value: "",
		label: "كل المراكز والأقسام"
	}];
	return nodesToOptions(getMarkazesForGovernorate(governorateId), "كل المراكز والأقسام");
}
function getCityOptionsForFilter(markazId) {
	if (!markazId) return [{
		value: "",
		label: "كل المدن والأحياء"
	}];
	return nodesToOptions(getCitiesForMarkaz(markazId), "كل المدن والأحياء");
}
function getVillageOptionsForFilter(cityId) {
	if (!cityId) return {
		options: [{
			value: "",
			label: "كل القرى والتجمعات"
		}],
		disabled: true,
		placeholder: "اختر المدينة / الحي أولاً"
	};
	const villages = getVillagesForCity(cityId);
	if (villages.length === 0) return {
		options: [{
			value: "",
			label: "لا توجد قرى مسجلة تحت هذا النطاق"
		}],
		disabled: true,
		placeholder: "لا توجد قرى مسجلة تحت هذا النطاق"
	};
	return {
		options: nodesToOptions(villages, "كل القرى والتجمعات"),
		disabled: false,
		placeholder: "كل القرى والتجمعات"
	};
}
